package store

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"net/url"
	"os"
	"strconv"
	"strings"
	"time"

	_ "modernc.org/sqlite"
)

// hashSessionToken hashes a session token before it ever touches the
// admin_sessions/user_sessions tables (P93) - the token is already a
// cryptographically random 256-bit value (generated by callers in admin.go),
// so a plain SHA-256 digest is sufficient; bcrypt's deliberate slowness is
// built for low-entropy passwords and buys nothing here.
func hashSessionToken(token string) string {
	sum := sha256.Sum256([]byte(token))
	return hex.EncodeToString(sum[:])
}

// CurrentSchemaVersion is the marbor.db schema version this binary understands.
// It is stamped into the settings table (key "schema_version") on every
// successful migrate(). migrate() is otherwise forward-only and unversioned
// (idempotent CREATE/ALTER, safe for older DBs) - this version check exists
// solely to catch the opposite direction: an older binary opening a DB a
// newer binary already wrote to. Bump only for a genuinely breaking
// marbor.db schema change, not for ordinary additive migrations.
const CurrentSchemaVersion = 1

// sqliteStore is the SQLite-backed Store implementation.
type sqliteStore struct {
	db        *sql.DB
	secretKey []byte // AES-256 key for at-rest secret encryption, see secretbox.go
}

// Open opens (or creates) a SQLite database at path, runs migrations, and
// returns a Store. The driver name is "sqlite" (modernc.org/sqlite, no CGO).
func Open(path string) (Store, error) {
	// Pragmas are encoded in the DSN (not run via db.Exec after Open) because
	// database/sql opens multiple physical connections under the hood; an
	// Exec-based PRAGMA only lands on whichever single connection ran it,
	// leaving the rest at driver defaults (busy_timeout=0), which caused
	// spurious SQLITE_BUSY under write contention. DSN pragmas are applied by
	// modernc.org/sqlite to every connection it opens.
	dsn := path
	if path != ":memory:" {
		dsn = path + "?_pragma=journal_mode(WAL)&_pragma=synchronous(NORMAL)&_pragma=busy_timeout(5000)&_pragma=foreign_keys(ON)"
	}
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("store: open %s: %w", path, err)
	}
	// WAL mode allows concurrent readers alongside a single writer; give the
	// pool enough connections to actually use that (SQLITE_BUSY on write
	// contention is absorbed by busy_timeout above).
	db.SetMaxOpenConns(4)
	db.SetMaxIdleConns(4)

	secretKey, err := loadOrCreateSecretKey(path)
	if err != nil {
		db.Close()
		return nil, fmt.Errorf("store: %w", err)
	}

	s := &sqliteStore{db: db, secretKey: secretKey}
	if err := s.migrate(); err != nil {
		db.Close()
		return nil, fmt.Errorf("store: migrate: %w", err)
	}

	// The DB stores secrets (API keys, session tokens, cloud provider keys).
	// By default SQLite creates the file with the process umask (often
	// world-readable 0644). Best-effort tighten to 0600 to match SaveConfig.
	// A failed chmod (e.g. on a filesystem that doesn't support it, or on
	// Windows where os.Chmod only toggles the read-only bit) must NOT break
	// startup, so errors are ignored. The pragmas/migrations above have
	// already forced the file (and WAL sidecars) to exist on disk.
	if path != "" && path != ":memory:" {
		_ = os.Chmod(path, 0o600)
		_ = os.Chmod(path+"-wal", 0o600)
		_ = os.Chmod(path+"-shm", 0o600)
	}

	return s, nil
}

// BackupTo writes a consistent snapshot of the live database to path using
// SQLite's VACUUM INTO. This runs against the same live *sql.DB handle Open
// configured with WAL + busy_timeout, so it is safe alongside concurrent
// readers and writers - no separate lock or file copy is needed. path must
// not already exist; VACUUM INTO errors if it does.
func (s *sqliteStore) BackupTo(path string) error {
	if _, err := s.db.Exec(`VACUUM INTO ?`, path); err != nil {
		return fmt.Errorf("store: backup to %s: %w", path, err)
	}
	return nil
}

// ValidateBackupFile opens path as its own independent SQLite connection and
// runs PRAGMA quick_check, verifying it is a genuine, non-corrupt database
// before a restore is ever allowed to act on it. This is intentionally a
// package-level function, not a Store method: it validates an arbitrary
// candidate FILE (a backup sitting on disk), not the live store the caller
// already has open. Callers (admin.go's restore handler) must call this
// before touching the live marbor.db - a bad file has to fail loudly here,
// before any swap happens, never discovered only after the live database is
// already gone.
func ValidateBackupFile(path string) error {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return fmt.Errorf("open %s: %w", path, err)
	}
	defer db.Close()
	var result string
	if err := db.QueryRow(`PRAGMA quick_check`).Scan(&result); err != nil {
		return fmt.Errorf("quick_check on %s: %w", path, err)
	}
	if result != "ok" {
		return fmt.Errorf("quick_check on %s reported: %s", path, result)
	}
	return nil
}

func (s *sqliteStore) migrate() error {
	// Settings table must exist before the version gate can read it, even on
	// a from-scratch DB. Idempotent - the full CREATE also appears later in
	// the stmts list below; running it twice is a harmless no-op.
	if _, err := s.db.Exec(`CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)`); err != nil {
		return fmt.Errorf("migrate: create settings table: %w", err)
	}
	if stored := GetIntSetting(s, "schema_version", 0); stored > CurrentSchemaVersion {
		return fmt.Errorf("marbor.db schema_version %d is newer than this binary supports (%d) - refusing to start; upgrade the binary or restore an older marbor.db backup", stored, CurrentSchemaVersion)
	}

	stmts := []string{
		`CREATE TABLE IF NOT EXISTS request_log (
			id             TEXT PRIMARY KEY,
			key_name       TEXT,
			model          TEXT,
			node_name      TEXT,
			status_code    INTEGER,
			latency_ms     INTEGER,
			tokens_used    INTEGER,
			cost_usd       REAL,
			routed_to      TEXT,
			is_cloud       INTEGER,
			ts             INTEGER,
			routing_reason TEXT,
			routing_detail TEXT
		)`,
		`CREATE INDEX IF NOT EXISTS request_log_ts ON request_log(ts DESC)`,

		`CREATE TABLE IF NOT EXISTS hourly_buckets (
			hour           INTEGER PRIMARY KEY,
			requests       INTEGER,
			tokens         INTEGER,
			cloud_requests INTEGER,
			local_requests INTEGER,
			cost_usd       REAL
		)`,

		`CREATE TABLE IF NOT EXISTS model_stats (
			model    TEXT PRIMARY KEY,
			requests INTEGER,
			tokens   INTEGER,
			cost_usd REAL
		)`,

		`CREATE TABLE IF NOT EXISTS counters (
			id              INTEGER PRIMARY KEY CHECK(id=1),
			local_requests  INTEGER,
			cloud_requests  INTEGER,
			total_tokens    INTEGER,
			cloud_spent_usd REAL
		)`,

		`CREATE TABLE IF NOT EXISTS key_counters (
			name         TEXT PRIMARY KEY,
			today        INTEGER,
			month        INTEGER,
			tokens_today INTEGER,
			tokens_month INTEGER,
			last_reset   INTEGER
		)`,

		`CREATE TABLE IF NOT EXISTS runtime_nodes (
			name         TEXT PRIMARY KEY,
			url          TEXT,
			runtime      TEXT,
			vram_total_mb INTEGER
		)`,

		// gpu_indices (added via ALTER TABLE below, same as runtime) is the
		// operator-declared physical GPU index list for this node (P75 Gap
		// B/C), JSON-encoded (e.g. "[0,1]") - same JSON-in-TEXT convention as
		// node_control.discovered_evidence. Empty string means "not declared".
		`CREATE TABLE IF NOT EXISTS node_overrides (
			name         TEXT PRIMARY KEY,
			vram_total_mb INTEGER,
			gpu_model    TEXT
		)`,

		`CREATE TABLE IF NOT EXISTS node_drain (
			name           TEXT PRIMARY KEY,
			draining       INTEGER,
			drained_reason TEXT NOT NULL DEFAULT ''
		)`,

		// marbor_agent holds the per-node Marbor Agent configuration (opaque
		// bearer token, port, enabled flag). Token is encrypted at rest
		// (enc:v1: prefix, see secretbox.go) by every writer below. scope
		// (P54: per-action token scoping) is NOT a secret - it's a plaintext
		// mirror of the tier embedded in token's own prefix, kept purely for
		// admin API observability (see MarborAgentRecord.Scope's doc comment
		// for why the agent never trusts this column for enforcement).
		// Default 'admin' matches every pre-P54 row's actual (unprefixed,
		// full-scope-by-fallback) token.
		// scheme (added post-P24 fix, see .local/specs/node-agent-tls.md's
		// dated correction note) is the Marbor Agent's OWN transport scheme
		// ("http" or "https") - independent of the runtime_nodes.url scheme
		// the same host's inference endpoint uses. Before this column
		// existed, every Marbor Agent URL builder derived its scheme from the
		// node's runtime URL instead, so enabling HTTPS for the agent also
		// silently switched the runtime endpoint to https:// and broke
		// runtimes (Ollama, vLLM, etc.) that only ever serve plain HTTP.
		// Default 'http' matches every pre-existing row's actual (plaintext)
		// agent transport.
		`CREATE TABLE IF NOT EXISTS marbor_agent (
			name    TEXT PRIMARY KEY,
			enabled INTEGER NOT NULL DEFAULT 0,
			port    INTEGER NOT NULL DEFAULT 0,
			token   TEXT NOT NULL DEFAULT '',
			scope   TEXT NOT NULL DEFAULT 'admin',
			scheme  TEXT NOT NULL DEFAULT 'http'
		)`,

		// node_control holds the per-node ControlDriver configuration (P43,
		// marbor-agent-capabilities.md section 5.5) - none of these columns
		// are secrets (no token/key here), unlike marbor_agent, so no
		// secretbox encryption applies. discovered_evidence is a JSON array
		// stored as TEXT, same convention as other JSON-in-TEXT columns in
		// this file (e.g. runtime_keys.models). configured is 0 until an
		// operator explicitly accepts a value (5.6) - never flipped by a
		// discovery re-scan.
		`CREATE TABLE IF NOT EXISTS node_control (
			name                  TEXT PRIMARY KEY,
			driver                TEXT NOT NULL DEFAULT '',
			identifier            TEXT NOT NULL DEFAULT '',
			configured            INTEGER NOT NULL DEFAULT 0,
			discovered_driver     TEXT NOT NULL DEFAULT '',
			discovered_identifier TEXT NOT NULL DEFAULT '',
			discovered_evidence   TEXT NOT NULL DEFAULT '[]',
			start_command         TEXT NOT NULL DEFAULT ''
		)`,

		`CREATE TABLE IF NOT EXISTS predictive_history (
			id         INTEGER PRIMARY KEY AUTOINCREMENT,
			from_model TEXT NOT NULL,
			to_model   TEXT NOT NULL,
			ts         TEXT NOT NULL
		)`,

		`CREATE TABLE IF NOT EXISTS runtime_keys (
			name          TEXT PRIMARY KEY,
			key           TEXT,
			rate_limit    INTEGER,
			daily_limit   INTEGER,
			monthly_limit INTEGER,
			daily_usd_cap REAL NOT NULL DEFAULT 0,
			monthly_usd_cap REAL NOT NULL DEFAULT 0,
			models        TEXT,
			revoked       INTEGER,
			expires_at    TEXT NOT NULL DEFAULT ''
		)`,

		`CREATE TABLE IF NOT EXISTS audit_log (
			id             INTEGER PRIMARY KEY AUTOINCREMENT,
			ts             TEXT NOT NULL,
			request_id     TEXT NOT NULL,
			key_name       TEXT NOT NULL,
			model          TEXT NOT NULL,
			node           TEXT NOT NULL,
			status         TEXT NOT NULL,
			latency_ms     INTEGER NOT NULL,
			cloud          INTEGER NOT NULL DEFAULT 0,
			cloud_model    TEXT NOT NULL DEFAULT '',
			routing_reason TEXT NOT NULL DEFAULT ''
		)`,
		`CREATE INDEX IF NOT EXISTS idx_audit_log_ts ON audit_log(ts DESC)`,
		// Composite index backing QueryAuditLog's filterable columns (key_name
		// equality, model LIKE prefix, node, ts range) so filtered lookups on
		// the Requests admin page stay fast as audit_log grows past hundreds
		// of thousands of rows. IF NOT EXISTS makes this a no-op after the
		// first boot on existing DBs.
		`CREATE INDEX IF NOT EXISTS idx_audit_log_filters ON audit_log (key_name, model, node, ts)`,

		`CREATE TABLE IF NOT EXISTS admin_credentials (
			id            INTEGER PRIMARY KEY CHECK(id=1),
			username      TEXT NOT NULL DEFAULT 'admin',
			password_hash TEXT NOT NULL,
			salt          TEXT NOT NULL
		)`,

		`CREATE TABLE IF NOT EXISTS admin_sessions (
			token      TEXT PRIMARY KEY,
			created_at INTEGER NOT NULL,
			expires_at INTEGER NOT NULL
		)`,

		`CREATE TABLE IF NOT EXISTS users (
			id                   INTEGER PRIMARY KEY AUTOINCREMENT,
			username             TEXT NOT NULL UNIQUE COLLATE NOCASE,
			email                TEXT NOT NULL DEFAULT '',
			password_hash        TEXT NOT NULL DEFAULT '',
			salt                 TEXT NOT NULL DEFAULT '',
			role                 TEXT NOT NULL DEFAULT 'user'
			                     CHECK(role IN ('admin','user')),
			status               TEXT NOT NULL DEFAULT 'pending'
			                     CHECK(status IN ('pending','active','suspended')),
			api_key_name         TEXT NOT NULL DEFAULT '',
			must_change_password INTEGER NOT NULL DEFAULT 0,
			skip_password_count  INTEGER NOT NULL DEFAULT 0,
			created_at           INTEGER NOT NULL,
			approved_at          INTEGER,
			approved_by          TEXT NOT NULL DEFAULT ''
		)`,

		`CREATE TABLE IF NOT EXISTS user_sessions (
			token                TEXT PRIMARY KEY,
			user_id              INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
			role                 TEXT NOT NULL,
			username             TEXT NOT NULL,
			must_change_password INTEGER NOT NULL DEFAULT 0,
			created_at           INTEGER NOT NULL,
			expires_at           INTEGER NOT NULL
		)`,

		`CREATE TABLE IF NOT EXISTS favorites (
			user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
			model_id   TEXT NOT NULL,
			created_at TEXT NOT NULL DEFAULT (datetime('now')),
			PRIMARY KEY (user_id, model_id)
		)`,

		`CREATE TABLE IF NOT EXISTS settings (
			key   TEXT PRIMARY KEY,
			value TEXT NOT NULL
		)`,

		`CREATE TABLE IF NOT EXISTS system_audit_log (
			id        INTEGER PRIMARY KEY AUTOINCREMENT,
			ts        TEXT NOT NULL,
			username  TEXT NOT NULL,
			action    TEXT NOT NULL,
			target    TEXT NOT NULL,
			details   TEXT NOT NULL,
			source_ip TEXT NOT NULL
		)`,
		`CREATE INDEX IF NOT EXISTS idx_system_audit_log_ts ON system_audit_log(ts DESC)`,

		`CREATE TABLE IF NOT EXISTS cloud_providers (
			name               TEXT PRIMARY KEY,
			provider           TEXT NOT NULL,
			base_url           TEXT NOT NULL,
			api_key            TEXT NOT NULL DEFAULT '',
			default_model      TEXT NOT NULL DEFAULT '',
			cost_per_1k_tokens REAL NOT NULL DEFAULT 0.0,
			enabled            INTEGER NOT NULL DEFAULT 1,
			priority           INTEGER NOT NULL DEFAULT 0
		)`,

		`CREATE TABLE IF NOT EXISTS routing_rules (
			id         TEXT PRIMARY KEY,
			condition  TEXT NOT NULL,
			target     TEXT NOT NULL,
			priority   INTEGER NOT NULL DEFAULT 0,
			enabled    INTEGER NOT NULL DEFAULT 1,
			created_at INTEGER NOT NULL
		)`,

		`CREATE TABLE IF NOT EXISTS warmup_config (
			id         INTEGER PRIMARY KEY CHECK(id=1),
			enabled    INTEGER NOT NULL DEFAULT 0,
			keep_alive TEXT NOT NULL DEFAULT '10m'
		)`,

		`CREATE TABLE IF NOT EXISTS warmup_models (
			model      TEXT PRIMARY KEY,
			nodes_json TEXT NOT NULL DEFAULT '[]'
		)`,

		// warm_state is the persisted model residency map (Phase 1: Persistent
		// Warm State). Rows survive a restart so the router starts warm.
		`CREATE TABLE IF NOT EXISTS warm_state (
			model      TEXT NOT NULL,
			node       TEXT NOT NULL,
			last_used  INTEGER NOT NULL DEFAULT 0,
			vram_bytes INTEGER NOT NULL DEFAULT 0,
			load_count INTEGER NOT NULL DEFAULT 0,
			PRIMARY KEY (model, node)
		)`,

		// session_affinity is the persisted sticky-session -> node pinning map
		// (AffinityRecord). SnapshotAffinity replaces the whole table's
		// contents each flush - it mirrors the in-memory map's own bounded,
		// TTL-swept lifecycle rather than growing forever.
		`CREATE TABLE IF NOT EXISTS session_affinity (
			session_id TEXT PRIMARY KEY,
			node_url   TEXT NOT NULL,
			last_seen  INTEGER NOT NULL DEFAULT 0
		)`,

		// model_configs holds the operator-declared default parameter profile
		// per (model, node) pair (item #20 - advanced model config overrides).
		// Keyed by node, not just model: the same model name can be resident
		// on nodes with different runtimes (Ollama/vLLM/TGI/llama.cpp) or just
		// different VRAM budgets, and a single shared-by-model-name profile
		// can't express either case. The full profile (30 load-time/
		// inference-time/meta fields, see ModelConfig) is stored as one JSON
		// blob rather than one column per field, matching the existing
		// runtime_keys.models / warmup_models.nodes_json idiom in this file  --
		// there's no need to filter/sort by individual param, only to fetch
		// the whole profile by (model, node).
		`CREATE TABLE IF NOT EXISTS model_configs (
			model       TEXT NOT NULL,
			node        TEXT NOT NULL,
			config_json TEXT NOT NULL,
			PRIMARY KEY (model, node)
		)`,

		// benchmark_runs is the history table for the in-dashboard hardware
		// benchmark page (evict -> N cold samples -> N warm samples via the
		// marbor's own /v1/chat/completions). No secrets here - R8 doesn't apply.
		// spill_counters is a durable, increment-in-place count of requests
		// per key x served_by ("local", a cloud provider name, or "blocked"
		// for a local_only policy rejection). Bounded by keys x providers -
		// never grows with request volume, unlike request_log. Rows are
		// historical telemetry: deleting an API key never deletes its rows
		// here (no FK/cascade to runtime_keys).
		`CREATE TABLE IF NOT EXISTS spill_counters (
			key_name  TEXT NOT NULL,
			served_by TEXT NOT NULL,
			requests  INTEGER NOT NULL DEFAULT 0,
			PRIMARY KEY (key_name, served_by)
		)`,

		`CREATE TABLE IF NOT EXISTS benchmark_runs (
			id           INTEGER PRIMARY KEY AUTOINCREMENT,
			node         TEXT NOT NULL,
			model        TEXT NOT NULL,
			n            INTEGER NOT NULL,
			cold_p50_ms  REAL NOT NULL,
			cold_min_ms  REAL NOT NULL,
			cold_max_ms  REAL NOT NULL,
			warm_p50_ms  REAL NOT NULL,
			warm_min_ms  REAL NOT NULL,
			warm_max_ms  REAL NOT NULL,
			speedup_x    REAL NOT NULL,
			created_at   INTEGER NOT NULL
		)`,
	}
	for _, stmt := range stmts {
		if _, err := s.db.Exec(stmt); err != nil {
			return fmt.Errorf("migrate stmt: %w\nSQL: %s", err, stmt)
		}
	}
	if err := s.migrateModelConfigsToNodeKeyed(); err != nil {
		return fmt.Errorf("migrate model_configs to (model,node) key: %w", err)
	}
	// Idempotent column additions for schema upgrades on existing DBs.
	for _, col := range []string{
		`ALTER TABLE users ADD COLUMN deleted_at INTEGER`,
		`ALTER TABLE users ADD COLUMN deleted_by TEXT NOT NULL DEFAULT ''`,
		`ALTER TABLE users ADD COLUMN skip_password_count INTEGER NOT NULL DEFAULT 0`,
		`ALTER TABLE hourly_buckets ADD COLUMN gen_duration_ms INTEGER NOT NULL DEFAULT 0`,
		`ALTER TABLE runtime_keys ADD COLUMN daily_usd_cap REAL NOT NULL DEFAULT 0`,
		`ALTER TABLE runtime_keys ADD COLUMN monthly_usd_cap REAL NOT NULL DEFAULT 0`,
		`ALTER TABLE runtime_keys ADD COLUMN expires_at TEXT NOT NULL DEFAULT ''`,
		`ALTER TABLE runtime_keys ADD COLUMN local_only INTEGER NOT NULL DEFAULT 0`,
		`ALTER TABLE runtime_keys ADD COLUMN allow_local_degradation INTEGER NOT NULL DEFAULT 0`,
		`ALTER TABLE node_drain ADD COLUMN drained_reason TEXT NOT NULL DEFAULT ''`,
		`ALTER TABLE node_overrides ADD COLUMN runtime TEXT`,
		`ALTER TABLE node_overrides ADD COLUMN gpu_indices TEXT NOT NULL DEFAULT ''`,
		// P64: per-node in-flight cap override. Nullable like vram_total_mb -
		// NULL means "no override declared" (falls back to
		// RoutingConfig.MaxInFlightPerNode), distinct from an explicit 0.
		`ALTER TABLE node_overrides ADD COLUMN max_in_flight INTEGER`,
		// P24: TOFU-pinned SHA-256 fingerprint of the Marbor agent's TLS cert.
		// Nullable - NULL means "no pin, this node is plaintext or not yet
		// TLS-enrolled". Not secret material (secretbox.go does not apply):
		// a cert fingerprint is public, and the private key never leaves the
		// node's own disk. See .local/specs/node-agent-tls.md.
		`ALTER TABLE node_overrides ADD COLUMN tls_fingerprint TEXT`,
		`ALTER TABLE node_control ADD COLUMN start_command TEXT NOT NULL DEFAULT ''`,
		// host groups multiple runtime_nodes rows that live on the same
		// physical machine (e.g. Ollama on :11434 and vLLM on :8000 on one
		// box) so they can share one Marbor Agent enrollment/token instead of
		// each needing its own - see internal/router.AddNode for the
		// default-from-URL-hostname fallback when this is left empty.
		`ALTER TABLE runtime_nodes ADD COLUMN host TEXT`,
		// P54: per-action Marbor Agent token scoping - see marbor_agent's
		// table comment above for why 'admin' is the correct default for
		// rows that predate this column.
		`ALTER TABLE marbor_agent ADD COLUMN scope TEXT NOT NULL DEFAULT 'admin'`,
		// P41: per-request routing explainability. routing_reason is the short
		// top-level Reason (session_affinity | pinned_warm | score_based);
		// routing_detail is the JSON-encoded score breakdown (nil for
		// cloud-fallback requests, which have no router.RoutingDecision).
		`ALTER TABLE request_log ADD COLUMN routing_reason TEXT`,
		`ALTER TABLE request_log ADD COLUMN routing_detail TEXT`,
		// P41 fix (code review): the Requests page's list view reads
		// audit_log via QueryAuditLog, not request_log - routing_reason must
		// live here too or the reason badge never populates in production.
		`ALTER TABLE audit_log ADD COLUMN routing_reason TEXT NOT NULL DEFAULT ''`,
		// Marbor Agent transport scheme, decoupled from the runtime URL's own
		// scheme - see marbor_agent's table comment above.
		`ALTER TABLE marbor_agent ADD COLUMN scheme TEXT NOT NULL DEFAULT 'http'`,
	} {
		s.db.Exec(col) // ignore error - column may already exist
	}
	if err := s.migrateEncryptSecrets(); err != nil {
		return fmt.Errorf("migrate encrypt secrets: %w", err)
	}
	if err := s.migrateMarborAgentRekeyByHost(); err != nil {
		return fmt.Errorf("migrate marbor_agent rekey by host: %w", err)
	}
	if err := s.SetSetting("schema_version", strconv.Itoa(CurrentSchemaVersion)); err != nil {
		return fmt.Errorf("migrate: stamp schema_version: %w", err)
	}
	return nil
}

// migrateMarborAgentRekeyByHost moves any marbor_agent row still keyed by an old
// node name (from before host-scoping) onto its node's shared host key, so
// disable/enable/regenerate - which all operate by host post-fix - actually
// find the row. A row is left alone if its key already matches some node's
// host (already migrated, or coincidentally identical to the node's name).
// Idempotent: safe to run on every boot.
func (s *sqliteStore) migrateMarborAgentRekeyByHost() error {
	nodes, err := s.AllNodes()
	if err != nil {
		return fmt.Errorf("select runtime_nodes: %w", err)
	}
	nameToHost := make(map[string]string, len(nodes))
	hosts := make(map[string]bool, len(nodes))
	for _, n := range nodes {
		host := n.Host
		if host == "" {
			if u, err := url.Parse(n.URL); err == nil {
				host = u.Hostname()
			}
		}
		if host == "" {
			continue
		}
		nameToHost[n.Name] = host
		hosts[host] = true
	}

	rows, err := s.db.Query(`SELECT name FROM marbor_agent`)
	if err != nil {
		return fmt.Errorf("select marbor_agent: %w", err)
	}
	var keys []string
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			rows.Close()
			return fmt.Errorf("scan marbor_agent: %w", err)
		}
		keys = append(keys, name)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return fmt.Errorf("marbor_agent rows: %w", err)
	}

	for _, key := range keys {
		if hosts[key] {
			continue // already keyed by a valid host
		}
		host, ok := nameToHost[key]
		if !ok || host == key {
			continue // not a known node name, or would be a no-op rename
		}
		if _, err := s.db.Exec(
			`INSERT OR IGNORE INTO marbor_agent (name, enabled, port, token)
			 SELECT ?, enabled, port, token FROM marbor_agent WHERE name = ?`,
			host, key,
		); err != nil {
			return fmt.Errorf("rekey marbor_agent %s -> %s: %w", key, host, err)
		}
		if _, err := s.db.Exec(`DELETE FROM marbor_agent WHERE name = ?`, key); err != nil {
			return fmt.Errorf("delete legacy-keyed marbor_agent row %s: %w", key, err)
		}
		log.Printf("store: migrated marbor_agent config for %q to shared host key %q", key, host)
	}
	return nil
}

// migrateEncryptSecrets re-encrypts any secret column/setting still holding
// legacy plaintext (no enc:v1: prefix) from before at-rest encryption was
// added. Idempotent: rows already encrypted are left untouched, so this is
// safe to run on every boot.
func (s *sqliteStore) migrateEncryptSecrets() error {
	rows, err := s.db.Query(`SELECT name, api_key FROM cloud_providers`)
	if err != nil {
		return fmt.Errorf("select cloud_providers: %w", err)
	}
	type plain struct{ name, value string }
	var pending []plain
	for rows.Next() {
		var name, apiKey string
		if err := rows.Scan(&name, &apiKey); err != nil {
			rows.Close()
			return fmt.Errorf("scan cloud_providers: %w", err)
		}
		if apiKey != "" && !strings.HasPrefix(apiKey, secretEncPrefix) {
			pending = append(pending, plain{name, apiKey})
		}
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return fmt.Errorf("cloud_providers rows: %w", err)
	}
	for _, p := range pending {
		enc, err := encryptSecret(s.secretKey, p.value)
		if err != nil {
			return fmt.Errorf("encrypt cloud_providers.api_key for %s: %w", p.name, err)
		}
		if _, err := s.db.Exec(`UPDATE cloud_providers SET api_key=? WHERE name=?`, enc, p.name); err != nil {
			return fmt.Errorf("update cloud_providers.api_key for %s: %w", p.name, err)
		}
	}

	rows, err = s.db.Query(`SELECT name, key FROM runtime_keys`)
	if err != nil {
		return fmt.Errorf("select runtime_keys: %w", err)
	}
	pending = pending[:0]
	for rows.Next() {
		var name, key string
		if err := rows.Scan(&name, &key); err != nil {
			rows.Close()
			return fmt.Errorf("scan runtime_keys: %w", err)
		}
		if key != "" && !strings.HasPrefix(key, secretEncPrefix) {
			pending = append(pending, plain{name, key})
		}
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return fmt.Errorf("runtime_keys rows: %w", err)
	}
	for _, p := range pending {
		enc, err := encryptSecret(s.secretKey, p.value)
		if err != nil {
			return fmt.Errorf("encrypt runtime_keys.key for %s: %w", p.name, err)
		}
		if _, err := s.db.Exec(`UPDATE runtime_keys SET key=? WHERE name=?`, enc, p.name); err != nil {
			return fmt.Errorf("update runtime_keys.key for %s: %w", p.name, err)
		}
	}

	rows, err = s.db.Query(`SELECT name, token FROM marbor_agent`)
	if err != nil {
		return fmt.Errorf("select marbor_agent: %w", err)
	}
	pending = pending[:0]
	for rows.Next() {
		var name, token string
		if err := rows.Scan(&name, &token); err != nil {
			rows.Close()
			return fmt.Errorf("scan marbor_agent: %w", err)
		}
		if token != "" && !strings.HasPrefix(token, secretEncPrefix) {
			pending = append(pending, plain{name, token})
		}
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return fmt.Errorf("marbor_agent rows: %w", err)
	}
	for _, p := range pending {
		enc, err := encryptSecret(s.secretKey, p.value)
		if err != nil {
			return fmt.Errorf("encrypt marbor_agent.token for %s: %w", p.name, err)
		}
		if _, err := s.db.Exec(`UPDATE marbor_agent SET token=? WHERE name=?`, enc, p.name); err != nil {
			return fmt.Errorf("update marbor_agent.token for %s: %w", p.name, err)
		}
	}

	for settingKey := range sensitiveSettingKeys {
		var value string
		err := s.db.QueryRow(`SELECT value FROM settings WHERE key=?`, settingKey).Scan(&value)
		if err == sql.ErrNoRows {
			continue
		}
		if err != nil {
			return fmt.Errorf("select settings %s: %w", settingKey, err)
		}
		if value == "" || strings.HasPrefix(value, secretEncPrefix) {
			continue
		}
		enc, err := encryptSecret(s.secretKey, value)
		if err != nil {
			return fmt.Errorf("encrypt settings %s: %w", settingKey, err)
		}
		if _, err := s.db.Exec(`UPDATE settings SET value=? WHERE key=?`, enc, settingKey); err != nil {
			return fmt.Errorf("update settings %s: %w", settingKey, err)
		}
	}
	return nil
}

// --- Request log ---

func (s *sqliteStore) AppendRequest(r RequestRecord) error {
	isCloud := 0
	if r.IsCloud {
		isCloud = 1
	}
	_, err := s.db.Exec(
		`INSERT OR IGNORE INTO request_log
			(id, key_name, model, node_name, status_code, latency_ms, tokens_used, cost_usd, routed_to, is_cloud, ts, routing_reason, routing_detail)
			VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		r.ID, r.KeyName, r.Model, r.NodeName, r.StatusCode, r.LatencyMs, r.TokensUsed, r.CostUSD, r.RoutedTo, isCloud, r.TS.Unix(), r.RoutingReason, r.RoutingDetail,
	)
	if err != nil {
		return fmt.Errorf("store: AppendRequest: %w", err)
	}
	// Trim to last 1000 rows.
	_, err = s.db.Exec(
		`DELETE FROM request_log WHERE id NOT IN (SELECT id FROM request_log ORDER BY ts DESC LIMIT 1000)`,
	)
	if err != nil {
		return fmt.Errorf("store: AppendRequest trim: %w", err)
	}
	return nil
}

func (s *sqliteStore) LastRequests(n int) ([]RequestRecord, error) {
	rows, err := s.db.Query(
		`SELECT id, key_name, model, node_name, status_code, latency_ms, tokens_used, cost_usd, routed_to, is_cloud, ts, routing_reason, routing_detail
		 FROM request_log ORDER BY ts DESC LIMIT ?`, n,
	)
	if err != nil {
		return nil, fmt.Errorf("store: LastRequests: %w", err)
	}
	defer rows.Close()

	var recs []RequestRecord
	for rows.Next() {
		var r RequestRecord
		var isCloud int
		var ts int64
		var reason, detail sql.NullString
		if err := rows.Scan(
			&r.ID, &r.KeyName, &r.Model, &r.NodeName, &r.StatusCode,
			&r.LatencyMs, &r.TokensUsed, &r.CostUSD, &r.RoutedTo, &isCloud, &ts, &reason, &detail,
		); err != nil {
			return nil, fmt.Errorf("store: LastRequests scan: %w", err)
		}
		r.IsCloud = isCloud != 0
		r.TS = time.Unix(ts, 0).UTC()
		r.RoutingReason = reason.String
		r.RoutingDetail = detail.String
		recs = append(recs, r)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: LastRequests rows: %w", err)
	}
	// Reverse to ascending order (oldest first).
	for i, j := 0, len(recs)-1; i < j; i, j = i+1, j-1 {
		recs[i], recs[j] = recs[j], recs[i]
	}
	return recs, nil
}

// GetRequest looks up one request_log row by id - the P41 explain endpoint's
// fallback for a request that has aged out of the bounded in-memory ring but
// is still within the SQLite table's 1000-row retention window.
func (s *sqliteStore) GetRequest(id string) (RequestRecord, bool, error) {
	var r RequestRecord
	var isCloud int
	var ts int64
	var reason, detail sql.NullString
	err := s.db.QueryRow(
		`SELECT id, key_name, model, node_name, status_code, latency_ms, tokens_used, cost_usd, routed_to, is_cloud, ts, routing_reason, routing_detail
		 FROM request_log WHERE id = ?`, id,
	).Scan(
		&r.ID, &r.KeyName, &r.Model, &r.NodeName, &r.StatusCode,
		&r.LatencyMs, &r.TokensUsed, &r.CostUSD, &r.RoutedTo, &isCloud, &ts, &reason, &detail,
	)
	if err == sql.ErrNoRows {
		return RequestRecord{}, false, nil
	}
	if err != nil {
		return RequestRecord{}, false, fmt.Errorf("store: GetRequest: %w", err)
	}
	r.IsCloud = isCloud != 0
	r.TS = time.Unix(ts, 0).UTC()
	r.RoutingReason = reason.String
	r.RoutingDetail = detail.String
	return r, true, nil
}

// --- Analytics ---

// UpsertHourlyBucket ADDS the given counts to the bucket for its hour. Callers
// pass a single request's delta (e.g. local_requests:1); the values accumulate
// per hour so that after a restart restoreFromStore reads real cumulative totals
// rather than the last request's values. (INSERT OR REPLACE previously clobbered
// the row on every request, persisting only the final request's counts.)
func (s *sqliteStore) UpsertHourlyBucket(b HourlyBucket) error {
	hourUnix := b.Hour.Truncate(time.Hour).Unix()
	_, err := s.db.Exec(
		`INSERT INTO hourly_buckets
			(hour, requests, tokens, cloud_requests, local_requests, cost_usd, gen_duration_ms)
			VALUES (?, ?, ?, ?, ?, ?, ?)
		 ON CONFLICT(hour) DO UPDATE SET
			requests        = requests + excluded.requests,
			tokens          = tokens + excluded.tokens,
			cloud_requests  = cloud_requests + excluded.cloud_requests,
			local_requests  = local_requests + excluded.local_requests,
			cost_usd        = cost_usd + excluded.cost_usd,
			gen_duration_ms = gen_duration_ms + excluded.gen_duration_ms`,
		hourUnix, b.Requests, b.Tokens, b.CloudRequests, b.LocalRequests, b.CostUSD, b.GenDurationMs,
	)
	if err != nil {
		return fmt.Errorf("store: UpsertHourlyBucket: %w", err)
	}
	return nil
}

func (s *sqliteStore) HourlyBuckets(since time.Time) ([]HourlyBucket, error) {
	rows, err := s.db.Query(
		`SELECT hour, requests, tokens, cloud_requests, local_requests, cost_usd, gen_duration_ms
		 FROM hourly_buckets WHERE hour >= ? ORDER BY hour ASC`,
		since.Unix(),
	)
	if err != nil {
		return nil, fmt.Errorf("store: HourlyBuckets: %w", err)
	}
	defer rows.Close()

	var buckets []HourlyBucket
	for rows.Next() {
		var b HourlyBucket
		var hourUnix int64
		if err := rows.Scan(&hourUnix, &b.Requests, &b.Tokens, &b.CloudRequests, &b.LocalRequests, &b.CostUSD, &b.GenDurationMs); err != nil {
			return nil, fmt.Errorf("store: HourlyBuckets scan: %w", err)
		}
		b.Hour = time.Unix(hourUnix, 0).UTC()
		buckets = append(buckets, b)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: HourlyBuckets rows: %w", err)
	}
	return buckets, nil
}

// UpsertModelStat ADDS the given counts to the per-model row (same accumulate
// semantics as UpsertHourlyBucket - callers pass a single request's delta).
func (s *sqliteStore) UpsertModelStat(ms ModelStat) error {
	_, err := s.db.Exec(
		`INSERT INTO model_stats (model, requests, tokens, cost_usd)
		 VALUES (?, ?, ?, ?)
		 ON CONFLICT(model) DO UPDATE SET
			requests = requests + excluded.requests,
			tokens   = tokens + excluded.tokens,
			cost_usd = cost_usd + excluded.cost_usd`,
		ms.Model, ms.Requests, ms.Tokens, ms.CostUSD,
	)
	if err != nil {
		return fmt.Errorf("store: UpsertModelStat: %w", err)
	}
	return nil
}

func (s *sqliteStore) AllModelStats() ([]ModelStat, error) {
	rows, err := s.db.Query(
		`SELECT model, requests, tokens, cost_usd FROM model_stats ORDER BY requests DESC`,
	)
	if err != nil {
		return nil, fmt.Errorf("store: AllModelStats: %w", err)
	}
	defer rows.Close()

	var stats []ModelStat
	for rows.Next() {
		var ms ModelStat
		if err := rows.Scan(&ms.Model, &ms.Requests, &ms.Tokens, &ms.CostUSD); err != nil {
			return nil, fmt.Errorf("store: AllModelStats scan: %w", err)
		}
		stats = append(stats, ms)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: AllModelStats rows: %w", err)
	}
	return stats, nil
}

