func (s *sqliteStore) AllWarmState() ([]WarmStateRecord, error) {
	rows, err := s.db.Query(
		`SELECT model, node, last_used, vram_bytes, load_count FROM warm_state`,
	)
	if err != nil {
		return nil, fmt.Errorf("store: AllWarmState: %w", err)
	}
	defer rows.Close()

	var out []WarmStateRecord
	for rows.Next() {
		var w WarmStateRecord
		var lastUsed int64
		if err := rows.Scan(&w.Model, &w.Node, &lastUsed, &w.VRAMBytes, &w.LoadCount); err != nil {
			return nil, fmt.Errorf("store: AllWarmState scan: %w", err)
		}
		w.LastUsed = warmUnixToUsed(lastUsed)
		out = append(out, w)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: AllWarmState rows: %w", err)
	}
	return out, nil
}

// --- Session affinity (sticky-session -> node map) ---

// SnapshotAffinity replaces the entire session_affinity table's contents with
// exactly the given entries, in one transaction. A full replace (not an
// incremental upsert) matches the in-memory affinity map's own lifecycle -
// entries the map no longer holds (expired, evicted) must not linger forever
// as stale rows.
func (s *sqliteStore) SnapshotAffinity(entries []AffinityRecord) error {
	tx, err := s.db.Begin()
	if err != nil {
		return fmt.Errorf("store: SnapshotAffinity begin: %w", err)
	}
	defer tx.Rollback()

	if _, err := tx.Exec(`DELETE FROM session_affinity`); err != nil {
		return fmt.Errorf("store: SnapshotAffinity delete: %w", err)
	}
	for _, e := range entries {
		if _, err := tx.Exec(
			`INSERT INTO session_affinity (session_id, node_url, last_seen) VALUES (?, ?, ?)`,
			e.SessionID, e.NodeURL, warmUsedToUnix(e.LastSeen),
		); err != nil {
			return fmt.Errorf("store: SnapshotAffinity insert: %w", err)
		}
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("store: SnapshotAffinity commit: %w", err)
	}
	return nil
}

func (s *sqliteStore) AllAffinity() ([]AffinityRecord, error) {
	rows, err := s.db.Query(`SELECT session_id, node_url, last_seen FROM session_affinity`)
	if err != nil {
		return nil, fmt.Errorf("store: AllAffinity: %w", err)
	}
	defer rows.Close()

	var out []AffinityRecord
	for rows.Next() {
		var e AffinityRecord
		var lastSeen int64
		if err := rows.Scan(&e.SessionID, &e.NodeURL, &lastSeen); err != nil {
			return nil, fmt.Errorf("store: AllAffinity scan: %w", err)
		}
		e.LastSeen = warmUnixToUsed(lastSeen)
		out = append(out, e)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: AllAffinity rows: %w", err)
	}
	return out, nil
}

// ReconcileNodeWarmState makes the persisted residency for a node exactly match
// the live /api/ps truth by deleting every warm_state row for the node whose
// model is NOT in residentModels. When residentModels is empty every row for
// that node is deleted. A single SQL statement is used; no row-by-row loop.
func (s *sqliteStore) ReconcileNodeWarmState(node string, residentModels []string) error {
	if len(residentModels) == 0 {
		// Fast path: node is fully cold - clear it entirely.
		_, err := s.db.Exec(`DELETE FROM warm_state WHERE node = ?`, node)
		if err != nil {
			return fmt.Errorf("store: ReconcileNodeWarmState clear %s: %w", node, err)
		}
		return nil
	}

	// Build a single DELETE … WHERE node = ? AND model NOT IN (?, ?, …).
	// We build the placeholder list once; SQLite handles the IN clause natively.
	placeholders := make([]string, len(residentModels))
	args := make([]any, 0, 1+len(residentModels))
	args = append(args, node)
	for i, m := range residentModels {
		placeholders[i] = "?"
		args = append(args, m)
	}
	query := `DELETE FROM warm_state WHERE node = ? AND model NOT IN (` +
		strings.Join(placeholders, ",") + `)`
	if _, err := s.db.Exec(query, args...); err != nil {
		return fmt.Errorf("store: ReconcileNodeWarmState %s: %w", node, err)
	}
	return nil
}

